import {fresh,restore,KEY,xp,level,award,finish} from './state.js';
import {REGIONS,WORLD,move,pathTo,camera,walkable} from './world.js';
import {EPISODES,FUTURES,NPCS} from './story.js';
import {routeReady} from './models.js';
import {renderActivity,handleActivity,initModels} from './activities.js';
import {fieldPanel,fieldAction} from './field.js';

const $=s=>document.querySelector(s),canvas=$('#world'),ctx=canvas.getContext('2d'),panel=$('#panel');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,act,extra='')=>{const match=extra.match(/class="([^"]*)"/),cls=match?match[1]:'btn';return `<button class="${cls}" data-act="${act}" ${extra.replace(/class="[^"]*"/,'')}>${text}</button>`;};
let state,core,playerFrames,npcFrames,earth,images={},started=false,flight=false,flightPos={x:.55,y:.3},flightGoal=null,flightAngle=146,route=[],arrivalId=null,keys=new Set(),moving=false,gaitTime=0,facing='south',view={x:0,y:0},scale=.8,last=0,activity=null,npcIndex=null,npcTopic=null,message='',previousImage=null,transition=0,toastTimer,showSpots=false,speechOn=false;
const admin={active:false,backup:null,started:false,flight:false,flightPos:null};
let contextSignature='';
function contextHTML(html){if(html!==contextSignature){$('#context').innerHTML=html;contextSignature=html;}}
const destinations=[{region:'coast',x:.54,y:.30,name:'Het kustobservatorium',description:'Klimaat, dezelfde plek in twee toekomsten en natuurgrenzen.'},{region:'workshop',x:.512,y:.205,name:'De haven van hergebruik',description:'Energie, producten, circulariteit en waarde voor meerdere partijen.'},{region:'valley',x:.592,y:.515,name:'De levende vallei',description:'Natuurlijke principes, herstel, terugkoppelingen en trage gevolgen.'},{region:'glacier',x:.515,y:.13,name:'Het gletsjerdal',description:'Een extra veldbezoek: volg sneeuw, smeltwater en het verschil tussen waarneming en bewijs.'},{region:'mangrove',x:.19,y:.47,name:'De mangrovekust',description:'Een extra veldbezoek: ontdek kustbescherming, natuurfuncties en wie van de kust leeft.'}];
const current=()=>EPISODES[state.episode],r=()=>REGIONS[state.region];
const concept=id=>core.concepts.find(c=>c.id===id);
const stepDone=id=>id==='visit-pressure'?state.visits.includes('pressure'):id==='visit-recovery'?state.visits.includes('recovery'):Boolean(state.flags[id]);
function persist(){if(!admin.active)localStorage.setItem(KEY,JSON.stringify(state));}
function stop(){keys.clear();route=[];arrivalId=null;flightGoal=null;moving=false;}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');$('#announcer').textContent=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function saveConcepts(ids){for(const id of ids||[])if(concept(id))award(state,id);persist();renderHUD();}
function imageKey(){return state.region==='coast'?`coast-${state.era}`:state.region;}
function showPanel(title,body,kicker='Je veldonderzoek'){stop();speechOn=false;$('#dialogue').hidden=true;activity=null;npcIndex=null;$('#panel-title').textContent=title;$('#panel-kicker').textContent=kicker;$('#panel-body').innerHTML=body+(admin.active&&title!=='Alle onderdelen van Atlas'?previewActions():'');if(!panel.open)panel.showModal();panel.scrollTop=0;$('#panel-title').setAttribute('tabindex','-1');$('#panel-title').focus({preventScroll:true});}
function previewActions(){return `<div class="panel-actions preview-actions">${btn('Docentenoverzicht','adminOverview')}${btn('Terug naar mijn gewone reis','adminExit')}</div>`;}
function closePanel(){panel.close();activity=null;message='';renderHUD();}
function showSpeech(name,text,actions=btn('Verder verkennen','endSpeech')){stop();panel.close();speechOn=true;$('#dialogue').hidden=false;$('#dialogue').innerHTML=`<small>${esc(name)}</small><p>${esc(text)}</p><div>${actions}</div>`;}
function landing(){started=false;stop();$('#landing').hidden=false;$('#hud').hidden=true;$('#objective').hidden=true;$('#context').hidden=true;$('#world-targets').hidden=true;$('#flight-targets').hidden=true;$('#mobile-controls').hidden=true;$('#landing').innerHTML=`<section class="start-overlay"><div class="start-copy"><p class="eyebrow">Duurzame waarde · een reis door de wereld</p><h1>ATLAS<br><em>Voorbij morgen.</em></h1><p class="lead">Loop de wereld in. Vlieg verder. Ontdek waarom ons klimaat verandert — en bezoek twee mogelijke toekomsten van dezelfde plek.</p><p class="promise">Je begint als Jules, zonder voorkennis. Onderzoek wat er gebeurt, probeer iets uit en ontdek onderweg de begrippen achter je keuzes.</p>${state.started?`<p class="saved">Je veldboek is bewaard. Je gaat verder bij <strong>${esc(current().name)}</strong>.</p>`:''}<div class="start-buttons">${btn(state.started?'Ga verder met je reis':'Begin de reis','start','class="btn btn-primary"')}${btn('Hoe werkt dit avontuur?','intro','class="btn quiet"')}</div></div><div class="start-bottom"><div class="start-meta"><span>Wandelend onderzoeken</span><span>De wereld overvliegen</span><span>Twee mogelijke toekomsten</span></div><span>Een oorspronkelijk avontuur · bronnen achter de ervaring</span></div></section>`;}
function start(){started=true;state.started=true;flight=false;$('#landing').hidden=true;$('#world-targets').hidden=false;$('#hud').hidden=false;$('#objective').hidden=false;$('#mobile-controls').hidden=false;initModels(state);if(!walkable(state.player,state.region))state.player={...r().spawn};persist();renderHUD();showSpeech('Jules · jouw reis begint',`${current().intro}`,btn('Ik ga op onderzoek','endSpeech')+btn('Mijn opdracht rustig bekijken','quest','class="btn quiet"'));}
function intro(){showPanel('Een wereld om te onderzoeken',`<p>Jij bent Jules, een veldonderzoeker bij Atlas. Je hoeft de theorie nog niet te kennen. Je begint bij de vraag wat klimaatverandering is en gaat daarna op reis naar energie, producten, natuur en besluiten.</p><p><strong>Lopen:</strong> WASD of pijltjestoetsen. Klik op de grond om erheen te lopen. Klik een onderzoekspunt aan of gebruik E als je dichtbij staat.</p><p><strong>Vliegen:</strong> stap bij de landingsplaats in Atlas. Bestuur met dezelfde toetsen, of kies een bestemming. Land bij een gemarkeerde regio.</p><p><strong>Toekomst:</strong> bezoek het tijdvenster in het kustobservatorium. De twee versies van 2060 zijn verbeelde mogelijkheden met verschillende aannames.</p><p>Je opdracht geeft houvast. Uitleg, NPC-vragen en hints zijn altijd beschikbaar. Je veldboek bewaart eigen notities. Een goed onderzocht antwoord verdient voortgang; vrij geschreven notities worden niet automatisch als juist beoordeeld.</p>${btn('Terug naar de wereld','close')}`, 'Jouw rol · je eerste vraag · de bediening');}
function renderHUD(){if(!state||!started)return;$('#hud').innerHTML=`<div class="hud-bar"><button class="brand" data-act="intro"><strong>ATLAS</strong><span>VOORBIJ MORGEN<br>Duurzame waarde</span></button><nav class="hud-nav" aria-label="Spelnavigatie"><span class="progress-chip">Level ${level(state)} · ${xp(state)} XP</span><button data-act="quest">Opdracht <kbd>Q</kbd></button><button data-act="map">Wereld <kbd>M</kbd></button><button data-act="book">Veldboek <kbd>N</kbd></button><button data-act="glossary" class="secondary">Begrippen</button><button data-act="settings" class="secondary">Bewaren</button><button data-act="admin" class="secondary">Docent</button></nav></div><div class="location"><small>${flight?'Wereldvlucht':state.era==='now'?'Jules op veldonderzoek':'Atlas · mogelijk toekomstbeeld'}</small><strong>${flight?'Onderweg boven de wereld':esc(r().name)}${state.era==='now'||flight?'':` · ${FUTURES[state.era].year}`}</strong>${state.era!=='now'&&!flight?`<p class="scenario">${esc(FUTURES[state.era].name)} · verbeeld scenario</p>`:''}</div>${admin.active?`<div class="preview-tag">Docentenpreview · ${btn('Overzicht','adminOverview')}${btn('Terug naar mijn reis','adminExit')}</div>`:''}<div class="walk-hint">${flight?'WASD / pijltjes om te vliegen · klik een bestemming · E om te landen':'WASD / pijltjes om te lopen · klik om te bewegen · E dichtbij · Esc sluit uitleg'}</div>`;renderObjective();}
function renderObjective(){if(!started)return;const e=current(),next=e.steps.find(([flag])=>!stepDone(flag)),complete=routeReady(state,e.id);$('#objective').innerHTML=`<section class="objective-box"><small>Reis ${state.episode+1} / ${EPISODES.length}</small><h2>${esc(e.name)}</h2><p>${esc(complete?'Je onderzoek is klaar. Neem je inzichten mee naar de volgende opdracht.':next?.[1]||e.goal)}</p>${complete?`<button class="complete" data-act="completeEpisode">${state.episode===7?'Bewaar je einddossier':'Neem het volgende spoor mee'} →</button>`:`<button data-act="quest">Bekijk de stappen en hulp</button>`}</section>`;}
function quest(){const e=current();showPanel(e.name,`<p>${esc(e.intro)}</p><div class="concept-box"><strong>Wat ontdek je?</strong><p>${esc(e.goal)}</p></div><ul class="step-list">${e.steps.map(([flag,label,kind])=>`<li class="${stepDone(flag)?'done':''}"><span class="mark">${stepDone(flag)?'✓':'○'}</span><div>${esc(label)}<br>${btn('Wijs deze plek aan','find','data-kind="'+kind+'"')}</div></li>`).join('')}</ul><p class="fine">Je hoeft niet ieder bijspoor te verzamelen om verder te kunnen. De bovenstaande inhoudelijke stappen bepalen deze opdracht.</p>${routeReady(state,e.id)?btn(state.episode===7?'Rond mijn dossier af':'Ga verder met het volgende spoor','completeEpisode','class="btn btn-primary"'):btn('Verder verkennen','close')}<details><summary>Ik wil meer hulp</summary><p>Open de uitleg bij een onderzoekspunt, vraag Sam, Ada of Amir door, en bekijk wat de proef werkelijk verandert. De basisuitleg is vanaf het begin beschikbaar.</p>${level(state)>=2?btn('Gebruik mijn spoorscanner','scan'):''}${level(state)>=3?btn('Gebruik mijn vergelijkingslens','compare'):''}</details>`, 'Situatie → onderzoek → inzicht');}
function findKind(kind){let region=state.region,spot=r().spots.find(p=>p.kind===kind||p.id===kind);if(!spot){for(const [id,reg]of Object.entries(REGIONS)){const p=reg.spots.find(p=>p.kind===kind||p.id===kind);if(p){region=id;spot=p;break;}}}return {region,spot};}
function find(kind){const {region,spot}=findKind(kind);closePanel();if(!spot){toast('Dit spoor wordt in een volgend deel van de reis uitgewerkt.');return;}if(region!==state.region){toast(`Dit onderzoek ligt in ${REGIONS[region].name}. Stap in Atlas en vlieg erheen.`);return;}showSpots=true;$('#world-targets').classList.add('show-spots');toast(`${spot.label} is aangewezen. Loop erheen of klik het punt aan.`);const el=document.querySelector(`[data-act=approach][data-id="${spot.id}"]`);el?.focus({preventScroll:true});}
function stepScan(){const next=current().steps.find(([flag])=>!stepDone(flag));if(next)find(next[2]);else quest();}
function approach(id){if(flight)return;const p=r().spots.find(p=>p.id===id);if(!p)return;speechOn=false;$('#dialogue').hidden=true;panel.close();keys.clear();route=pathTo(state.player,{x:p.x,y:p.y},state.region);arrivalId=id;if(!route.length){if(Math.hypot(state.player.x-p.x,state.player.y-p.y)<.105){arrivalId=null;interactSpot(p);}else toast('Loop via het zichtbare pad naar dit punt.');}}
function nearest(){return r().spots.map(p=>({...p,d:Math.hypot((p.x-state.player.x)*1.5,p.y-state.player.y)})).sort((a,b)=>a.d-b.d)[0];}
function interact(){if(flight){const destination=destinations.map(d=>({...d,dist:Math.hypot(d.x-flightPos.x,(d.y-flightPos.y)*.55)})).sort((a,b)=>a.dist-b.dist)[0];if(destination.dist<.035)land(destination.region);else toast('Vlieg dichter naar een gemarkeerde bestemming.');return;}const p=nearest();if(p&&p.d<.13)interactSpot(p);else toast('Loop dichter naar een persoon of onderzoekspunt, of klik het aan.');}
function interactSpot(p){stop();if(p.kind==='portal'){portal();return;}if(p.kind==='craft'){takeoff();return;}if(state.era!=='now'){futureObservation(p);return;}if(p.kind==='npc'){npc(p.npc);return;}if(p.kind==='field'){openField(p.id);return;}openActivity(p.kind);}
function openField(id,feedback=null){showPanel('Veldbezoek · '+r().name,fieldPanel(id,state)+(feedback?`<div class="feedback ${feedback.correct===false?'retry':''}" role="status">${esc(feedback.message)}</div>`:'')+btn('Verder door het landschap','close'),'Kijk rond · volg het proces · verbind het aan je reis');}
function fieldAnswer(el){const result=fieldAction(el.dataset.fieldId,el.dataset.value,state);saveConcepts(result.conceptIds);persist();openField(el.dataset.fieldId,result);renderHUD();}
function npc(index,topic=null){npcIndex=index;npcTopic=topic;const n=NPCS[index],t=topic==null?null:n.topics[topic];showPanel(`In gesprek met ${n.name}`,`<p class="compact">${esc(n.role)} · ${esc(r().name)}</p><p>${esc(t?.answer||n.opening)}</p><div class="choice-list">${n.topics.map((t,i)=>`<button data-act="npcTopic" data-npc="${index}" data-topic="${i}">${esc(t.question)}</button>`).join('')}</div>${btn('De begrippen rustig uitgelegd','episodeConcepts')}${btn('Mijn huidige opdracht','quest')}${btn('Terug naar de wereld','close')}`, 'Jij bepaalt wat je vraagt');npcIndex=index;}
function futureObservation(p){const pressure=state.era==='pressure',text=p.kind==='weather'||p.kind==='heat'?pressure?'De meetpost kan blijven werken, maar warmte en minder beschikbaar water zetten deze plek onder druk. Je ziet een verbeeld gevolg, geen bewijs uit een echte meetreeks. Mondiale uitstoot en lokale kwetsbaarheid spelen verschillende rollen.':'De meetpost helpt besluiten bijstellen. Wereldwijde uitstootreductie beperkt toekomstige opwarming; lokaal zorgen schaduw en wateropvang voor bescherming. Onderhoud en toegang vragen nog steeds keuzes.':p.kind==='water'||p.kind==='boundary'?pressure?'De omgeving heeft weinig schaduw en wateropvang. Dat maakt dezelfde hitte of regen zwaarder voor bewoners en het werk hier. Niet iedereen heeft evenveel middelen om zich te beschermen.':'Schaduw, opvang en een toegankelijke route verminderen lokale blootstelling. Die ingrepen nemen de oorzaak van mondiale opwarming niet vanzelf weg. Kijk ook wie de aanleg en het onderhoud betaalt.':pressure?'Dezelfde gebouwen staan er nog, maar droge vegetatie en beschadigde kustranden laten zien hoe verschillende gevolgen samen kunnen werken. Welke effecten komen door klimaat, welke door inrichting en voorbereiding?':'Je herkent dezelfde plek. De plantenstroken en onderhouden routes laten een andere inrichting zien. Dit is geen perfecte wereld: wie beheert die systemen en wie krijgt toegang als het water schaars wordt?';showPanel(`${FUTURES[state.era].name}: ${p.label}`,`<p>${esc(text)}</p><details><summary>Welke aannames horen bij dit beeld?</summary><p>${esc(FUTURES[state.era].assumptions)}</p></details>${btn('Leg deze waarneming vast','saveFuture','class="btn btn-primary"')}${btn('Terug naar het landschap','close')}`, '2060 · een mogelijke toekomst onderzoeken');}
function saveFuture(){if(!state.visits.includes(state.era))state.visits.push(state.era);saveConcepts(['climate-impact-chain']);closePanel();toast('Toekomstwaarneming bewaard. Vergelijk ook de andere mogelijkheid en keer terug naar het heden.');}
function portal(){showPanel('Het tijdvenster',`<p>Atlas brengt je naar dezelfde kustplek in twee verbeelde versies van 2060. Kijk rond, onderzoek een herkenningspunt en vergelijk daarna. Je hoeft geen toekomst te kiezen als “de juiste”.</p><div class="choice-list">${Object.entries(FUTURES).map(([era,v])=>`<button data-act="era" data-era="${era}"><strong>${v.year} · ${esc(v.name)}</strong><br><span class="fine">${esc(v.assumptions)}</span></button>`).join('')}</div>${btn('Vergelijk de twee toekomstbeelden','futureCompare')}<p class="fine">Personages en locaties zijn fictief. De klimaatprocessen en de grenzen van de uitleg zijn gebaseerd op de broncursus en gecontroleerde primaire bronnen.</p>`, 'Dezelfde plek · verschillende aannames');}
function futureCompare(){showPanel('Twee mogelijke toekomsten naast elkaar',`<p>De gebouwen en paden zijn gelijk. Vergelijk de vegetatie, schaduw, opvang en kustrand. Beide beelden zijn verbeeld, met verschillende aannames.</p><div class="future-comparison">${['pressure','recovery'].map(era=>`<figure><img src="assets/coast-${era}.webp" alt="${esc(FUTURES[era].name)} van dezelfde kustplaats"><figcaption><strong>${esc(FUTURES[era].name)}</strong><p>${esc(FUTURES[era].assumptions)}</p></figcaption></figure>`).join('')}</div><p>Wereldwijde uitstoot beïnvloedt hoeveel het klimaat opwarmt. Lokale schaduw, waterbeheer en toegang beïnvloeden hoe kwetsbaar deze plek is. Omdat beide veranderen, kun je het zichtbare verschil niet aan één maatregel toeschrijven.</p><label class="mini-note">Wat zie ik, en wat kan ik nog niet uit dit beeld afleiden?<textarea data-note="future-comparison">${esc(state.notes['future-comparison']||'')}</textarea></label>${btn('Terug naar het landschap','close')}`, 'Het tijdkompas · vergelijken zonder een perfecte toekomst te beloven');}
function toolUse(index){const kinds=['', '', 'power','product','value','water','loop'];if(index===0)futureCompare();else if(index===1)map();else if(kinds[index])openActivity(kinds[index]);else book();}
function setEra(era){if(!FUTURES[era])return;previousImage=images[imageKey()];state.region='coast';state.era=era;state.player={x:.46,y:.63};flight=false;transition=state.settings.motion?1:0;closePanel();persist();renderHUD();showSpeech('Atlas · tijdvenster',era==='now'?'Terug in het heden. Wat kun je nu anders doen op basis van wat je zag?':`${FUTURES[era].year}. ${FUTURES[era].name}. Loop naar een herkenningspunt om de gevolgen en aannames te onderzoeken. Het landschap is een verbeeld scenario.`);}
function takeoff(){if(!state.flags.greenhouse&&!admin.active){showSpeech('Sam', 'Atlas is bijna klaar voor vertrek. Onderzoek eerst het warmtepad bij de meetopstelling. Daarna kun je zelf over de wereld vliegen.',btn('Wijs de meetopstelling aan','find','data-kind="heat"')+btn('Terug naar de wereld','endSpeech','class="btn quiet"'));return;}stop();panel.close();speechOn=false;$('#dialogue').hidden=true;flight=true;flightPos={...destinations.find(d=>d.region===state.region)};flightGoal=null;renderHUD();toast('Atlas stijgt op. Bestuur met WASD of klik een bestemming. E landt als je dichtbij bent.');}
function land(region){if(!REGIONS[region])return;flight=false;flightGoal=null;state.region=region;state.era='now';state.player={...r().spawn};stop();persist();renderHUD();const description=destinations.find(d=>d.region===region)?.description;showSpeech('Jules',region===current().region?current().intro:`Je bent in ${r().name}. ${description} Loop naar een onderzoekspunt. Je kunt met Atlas terug naar jouw hoofdopdracht: ‘${current().name}’.`);}
function map(){showPanel('Waar brengt de reis je?',`<p>Je vliegt met Atlas tussen de gebieden en loopt ter plekke verder. Je hoofdopdracht houdt de leerroute samen; extra veldbezoeken laten je de processen op andere plekken ontdekken.</p><p class="fine">De markeringen stellen landschapstypen voor. Dit zijn fictieve onderzoekslocaties op een wereldkaart, geen voorspellingen voor die precieze coördinaten.</p>${destinations.map(d=>`<article class="episode-card"><h3>${esc(d.name)}</h3><p>${esc(d.description)}</p>${flight?btn('Vlieg naar deze bestemming','flyTo','data-region="'+d.region+'"'):d.region===state.region?btn('Verder in deze regio','close'):btn('Wijs Atlas aan','find','data-kind="craft"')}</article>`).join('')}${btn('Mijn verhaalroute','storyRoute')}`, 'De wereld ontdekken');}
function flyTo(region){const d=destinations.find(d=>d.region===region);if(!d)return;if(!flight){find('craft');return;}closePanel();flightGoal={x:d.x,y:d.y};toast(`Je vliegt naar ${d.name}. Je kunt de koers steeds zelf overnemen.`);}
function openActivity(kind){message='';showPanel(activityTitle(kind),'','Onderzoeken · proberen · begrijpen');activity=kind;renderCurrentActivity();}
function activityTitle(kind){return {weather:'Vandaag is niet het hele klimaat',heat:'Waar blijft de warmte?',boundary:'De grenzen die je samen moet zien',power:'Een energienet dat blijft werken',carrier:'Energie komt ergens vandaan',product:'Geef het product een passende route',contract:'Wie heeft belang bij langer gebruik?',value:'De waarde achter het bedrijf',biomimicry:'Leer een principe, test een ontwerp',water:state.episode===1?'Minder uitstoten of beter voorbereiden?':'Een proefveld voor water en schaduw',loop:'Een gevolg dat bij het begin terugkomt',delay:'Waarom wachten op het gevolg telt',decision:'Een besluit dat je kunt verantwoorden'}[kind]||'Veldonderzoek';}
function activityConcepts(kind){const map={weather:['climate-change','weather-climate'],heat:['greenhouse-energy-flow','human-emissions'],boundary:['planetary-boundaries','biodiversity-services','nutrients-water','system-boundary','sustainable-development','people-planet-prosperity'],power:['energy-transition','grid-congestion'],carrier:['emissions-accumulation','carbon-budget','energy-transition'],product:['linear-circular','r-ladder','design-for-long-life','life-cycle-assessment'],contract:['service-ownership','sharing-and-rebound'],value:['six-capitals','multiple-value-creation','double-materiality','stakeholder-perspectives','indicators'],biomimicry:['biomimicry','lifes-principles','regenerative-design'],water:state.episode===1?['mitigation-adaptation','climate-impact-chain']:['regenerative-design','lifes-principles'],loop:['systems-thinking','causal-loop-diagram','climate-feedback','tipping-points'],delay:['wicked-problems','lock-in-path-dependence','leverage-points'],decision:['decisions-under-uncertainty']};return (map[kind]||[]).map(concept).filter(Boolean);}
function renderCurrentActivity(preserve=true){if(!activity)return;const scroll=preserve?panel.scrollTop:0;$('#panel-body').innerHTML=renderActivity(activity,state,core.concepts)+`<details class="concept-help"><summary>De begrippen achter dit onderzoek eenvoudig uitgelegd</summary>${activityConcepts(activity).map(c=>`<div class="book-concept"><strong>${esc(c.term)}</strong><p>${esc(c.definition)}</p><p class="fine">Bijvoorbeeld: ${esc(c.beginnerExample)}</p></div>`).join('')}</details>${message?`<div class="feedback ${message.correct===false?'retry':''}" role="status">${esc(message.message)}</div>`:''}<div class="panel-actions">${btn('Terug naar de wereld','close')}${btn('Mijn opdracht en stappen','quest')}</div>${admin.active?previewActions():''}`;panel.scrollTop=scroll;if(message)$('#panel-body .feedback')?.scrollIntoView({block:'nearest'});}
function activityAction(el){const result=handleActivity(el.dataset.kind||activity,el.dataset.action,el.dataset.value,state)||{};if(result.conceptIds)saveConcepts(result.conceptIds);persist();message=result;renderCurrentActivity();renderHUD();}
function book(){showPanel('Mijn veldboek',`<p>Je waarnemingen en eigen redeneringen reizen mee. Ze blijven in deze browser bewaard.</p>${state.tools.length?`<details open><summary>Meegenomen gereedschap · ${state.tools.length}</summary><p class="fine">Neem je eerdere onderzoek mee naar een nieuwe afweging. Met deze gereedschappen kun je vergelijken en eerdere proeven opnieuw openen, waar je ook bent.</p><div class="hint-tools">${state.tools.map(tool=>{const index=EPISODES.findIndex(ep=>ep.reward===tool);return btn(esc(tool),'toolUse','data-index="'+index+'"');}).join('')}</div></details>`:''}<label class="field-label" for="notes">Mijn notities bij ${esc(current().name)}</label><textarea id="notes" data-note="${current().id}" placeholder="Wat zag ik? Waardoor gebeurde het? Wat verwacht ik bij een andere keuze?">${esc(state.notes[current().id]||'')}</textarea><p class="fine">Automatisch bewaard. Je notities krijgen geen automatische inhoudelijke beoordeling.</p><details open><summary>Onderzochte begrippen · ${state.concepts.length}</summary>${state.concepts.map(concept).filter(Boolean).map(c=>`<div class="book-concept"><strong>${esc(c.term)}</strong><p>${esc(c.definition)}</p></div>`).join('')||'<p>Je eerste inzichten worden hier vastgelegd.</p>'}</details><details><summary>Toekomstwaarnemingen</summary><p>${state.visits.map(e=>esc(FUTURES[e]?.name||e)).join(' · ')||'Nog geen toekomst onderzocht.'}</p></details><div class="panel-actions">${btn('Download mijn veldboek','export')}${btn('Levels en gereedschap','upgrades')}${level(state)>=3?btn('Vergelijk twee inzichten','compare'):''}</div>`, 'Bewaren · verbinden · terugvinden');}
function glossary(ids){const rows=ids?ids.map(concept).filter(Boolean):core.concepts;showPanel('Begrippen, in gewone taal',`<p>Je hoeft deze woorden vooraf niet te kennen. Open een begrip wanneer het in je onderzoek verschijnt.</p>${rows.filter(c=>c.priority!=='referenceOnly').map(c=>`<details><summary>${esc(c.term)}</summary><p>${esc(c.definition)}</p><p class="fine">Voorbeeld: ${esc(c.beginnerExample)}</p></details>`).join('')}<details><summary>Alleen als naslag: achtergrondbegrippen</summary>${rows.filter(c=>c.priority==='referenceOnly').map(c=>`<div class="book-concept"><strong>${esc(c.term)}</strong><p>${esc(c.definition)}</p></div>`).join('')}</details><p><a class="source-link" href="https://fabianb88.github.io/minor-ce-elearnings/player.html?c=duurzaamheid-fundamenten" target="_blank" rel="noopener">Open de oorspronkelijke e-learning ↗</a></p>`, 'Het idee eerst · de vakterm daarna');}
function compare(){const rows=state.concepts.map(concept).filter(Boolean);if(level(state)<3){upgrades();return;}showPanel('Mijn vergelijkingslens',`<p>Leg twee onderzochte ideeën naast elkaar. Welke oorzaak, grens of afweging verbindt ze?</p><div class="form-row">${[1,2].map(n=>`<select id="compare-${n}" aria-label="Begrip ${n}">${rows.map(c=>`<option value="${c.id}">${esc(c.term)}</option>`).join('')}</select>`).join('')}</div>${btn('Leg naast elkaar','compareShow')}<div id="comparison"></div><label class="field-label" for="connections">Mijn verbindingen</label><textarea id="connections" data-note="connections">${esc(state.notes.connections||'')}</textarea>`, 'Onderzoeksupgrade · eigen redenering');}
function compareShow(){const ids=[$('#compare-1').value,$('#compare-2').value];if(ids[0]===ids[1]){toast('Kies twee verschillende ideeën.');return;}$('#comparison').innerHTML=ids.map(concept).map(c=>`<div class="concept-box"><strong>${esc(c.term)}</strong><p>${esc(c.definition)}</p><p>${esc(c.beginnerExample)}</p></div>`).join('');}
function upgrades(){showPanel('Ervaring die iets oplevert',`<p>Je verdient 15 XP voor een nieuw onderzocht begrip en 150 XP voor een afgeronde verhaalopdracht. Herhaald klikken geeft geen extra XP. Dit is voortgang, geen morele score of bewijs van beheersing.</p><p><strong>Level ${level(state)} · ${xp(state)} XP</strong></p>${[[1,'Veldonderzoeker','Alle uitleg, NPC-vragen, hints en het veldboek zijn beschikbaar.'],[2,'Spoorzoeker','De spoorscanner wijst het volgende relevante onderzoekspunt aan.'],[3,'Verbinder','De vergelijkingslens legt twee onderzochte ideeën naast elkaar met ruimte voor je eigen verband.'],[4,'Routebouwer','Alle eerder bezochte episodes kun je rechtstreeks als herhaalroute openen.']].map(([l,title,text])=>`<article class="episode-card"><small>${level(state)>=l?'Vrijgespeeld':'Nog te bereiken'} · level ${l}</small><h3>${title}</h3><p>${text}</p></article>`).join('')}${level(state)>=2?btn('Spoorscanner gebruiken','scan'):''}${level(state)>=3?btn('Vergelijkingslens openen','compare'):''}`, 'Gereedschap voor je onderzoek');}
function completeEpisode(){const e=current();try{finish(state,e.id,routeReady(state,e.id));if(!state.tools.includes(e.reward))state.tools.push(e.reward);persist();if(state.episode===7){showPanel('Je Atlas-dossier',`<p>Je hebt de kernroute onderzocht: klimaat, twee mogelijke toekomsten, energie, circulariteit, brede waarde, natuurprincipes en systeemverandering.</p><p>Een goed besluit noemt wat het weet, welke aannames het gebruikt, wie gevolgen ondervindt en hoe het wordt gecontroleerd. Je eigen notities blijven onderdeel van je dossier.</p><label class="field-label" for="final-notes">Mijn voorstel en resterende vragen</label><textarea id="final-notes" data-note="final">${esc(state.notes.final||'')}</textarea>${btn('Download mijn dossier','export','class="btn btn-primary"')}${btn('Terug naar het kustobservatorium','revisit','data-index="0"')}${btn('De volledige bron en onderbouwing','research')}`, 'Je reis eindigt · het onderzoek gaat verder');return;}state.episode++;persist();renderHUD();showSpeech('Jules · een nieuw spoor',`${EPISODES[state.episode].intro} Je hebt ${e.reward.toLowerCase()} meegenomen.`,btn('Ik volg het spoor','endSpeech')+btn('Bekijk mijn nieuwe opdracht','quest','class="btn quiet"'));}catch(e){toast(e.message);}}
function storyRoute(){showPanel('Een samenhangende reis',EPISODES.map((e,n)=>`<article class="episode-card"><small>Reis ${n+1} · ${state.completed.includes(e.id)?'afgerond':n===state.episode?'huidig spoor':'later op de route'}</small><h3>${esc(e.name)}</h3><p>${esc(e.goal)}</p>${admin.active?btn('Controleer deze episode','adminVisit','data-index="'+n+'"'):level(state)>=4&&state.completed.includes(e.id)?btn('Herbezoek','revisit','data-index="'+n+'"'):''}</article>`).join(''),'Verschillende handelingen · één wereld');}
function revisit(n){if(!admin.active&&(level(state)<4||!state.completed.includes(EPISODES[n]?.id)))return;state.episode=n;state.region=EPISODES[n].region;state.era='now';state.player={...r().spawn};flight=false;closePanel();persist();renderHUD();}
function settings(){showPanel('Mijn reis bewaren',`<p>Jouw voortgang en veldboek staan op dit apparaat. Download een kopie om de reis elders te openen.</p>${btn('Download voortgang en veldboek','export')}<label class="btn">Open een opgeslagen reis<input type="file" id="import" accept="application/json,.json" hidden></label>${btn('Mijn levels en gereedschap','upgrades')}${btn('Onderbouwing en bouwplan','research')}${btn(state.settings.motion?'Rustiger beeld inschakelen':'Animatie inschakelen','motion')}${btn('Docentenweergave','admin')}${btn('Naar het beginscherm','home')}<details><summary>Een nieuwe reis beginnen</summary><p>Download eerst je veldboek als je je huidige reis wilt bewaren.</p>${btn('Begin opnieuw op dit apparaat','reset')}</details>`, 'Voortgang en toegankelijkheid');}
function exportSave(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='atlas-veldboek.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function research(){showPanel('Waarop is Atlas gebaseerd?',`<p>De inhoud komt uit ‘Duurzaamheid, circulariteit en systeemdenken’ via de studentenhandleiding. De docent kiest de leeressentie; achtergrondnamen van aardlagen zijn naslag.</p><p>De bronanalyse bevat 40 geselecteerde begrippen, waarvan 36 essentieel, met blokverwijzingen en correcties op basis van primaire bronnen. Je kunt de selectie en concrete leerhandelingen controleren in het bouwplan.</p><p>Het ontwerp gebruikt begeleid onderzoeken, begrijpelijke voorbeelden, toepassing, feedback en vergelijking. Bewegen of een mooi toekomstbeeld bekijken bewijst op zichzelf geen leerresultaat.</p><p><a class="source-link" href="plan.html" target="_blank" rel="noopener">Bekijk de inhoud, leerroute en ontwerpkeuzes ↗</a></p><p><a class="source-link" href="https://fabianb88.github.io/minor-ce-elearnings/player.html?c=duurzaamheid-fundamenten" target="_blank" rel="noopener">De oorspronkelijke e-learning ↗</a></p><details><summary>Primaire broncorrecties</summary>${core.corrections.map(c=>`<p>${esc(c.correction||c.correctedStatement||c.corrected||c.issue||JSON.stringify(c))}</p>`).join('')}</details>`, 'Bronnen · keuzes · grenzen van de claim');}
function adminPrompt(){if(admin.active){adminOverview();return;}showPanel('Docentenweergave',`<p>Controleer de regio’s, toekomstbeelden en opdrachten zonder de reis te doorlopen. De preview wijzigt je gewone veldboek niet.</p><label class="field-label" for="admin-code">Toegangscode</label><input id="admin-code" type="password" autocomplete="off"><div class="panel-actions">${btn('Open docentenweergave','adminLogin')}</div><p id="admin-error" class="fine"></p>`, 'Inhoud en werking bekijken');}
function adminLogin(){if($('#admin-code')?.value!=='fabian1'){$('#admin-error').textContent='Deze code klopt niet.';return;}admin.backup=structuredClone(state);admin.started=started;admin.flight=flight;admin.flightPos={...flightPos};admin.active=true;started=true;$('#landing').hidden=true;$('#world-targets').hidden=false;$('#hud').hidden=false;$('#objective').hidden=false;renderHUD();adminOverview();}
function adminOverview(){showPanel('Alle onderdelen van Atlas',`<p>Dit is een aparte preview. Testen, antwoorden en notities veranderen je gewone reis niet.</p>${EPISODES.map((e,n)=>`<article class="episode-card"><small>Reis ${n+1}</small><h3>${esc(e.name)}</h3><p>${esc(e.goal)}</p>${btn('Open deze episode','adminVisit','data-index="'+n+'"')}</article>`).join('')}<h3>Veldbezoeken</h3>${['glacier','mangrove'].map(region=>btn(esc(REGIONS[region].name),'adminRegion','data-region="'+region+'"')).join('')}<h3>Alle werkvormen</h3><div class="hint-tools">${['weather','heat','boundary','power','carrier','product','contract','value','biomimicry','water','loop','delay','decision'].map(kind=>btn(esc(activityTitle(kind)),'adminActivity','data-kind="'+kind+'"')).join('')}</div><h3>Toekomstbeelden</h3>${Object.keys(FUTURES).map(era=>btn(esc(FUTURES[era].name),'era','data-era="'+era+'"')).join('')}<div class="panel-actions">${btn('Terug naar mijn gewone reis','adminExit')}</div>`, 'Docentenpreview');}
function adminVisit(n){if(!admin.active)return;state.episode=n;state.region=EPISODES[n].region;state.era='now';state.player={...r().spawn};flight=false;initModels(state);closePanel();renderHUD();}
function adminActivity(kind){if(!admin.active)return;const {region}=findKind(kind);state.region=region;state.era='now';state.player={...r().spawn};flight=false;renderHUD();openActivity(kind);}
function adminExit(){if(!admin.active)return;state=admin.backup;started=admin.started;flight=admin.flight;flightPos=admin.flightPos||flightPos;admin.active=false;admin.backup=null;closePanel();if(started)renderHUD();else landing();}

function resize(){const dpr=Math.min(2,devicePixelRatio||1);canvas.width=Math.round(innerWidth*dpr);canvas.height=Math.round(innerHeight*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);scale=Math.max(innerWidth/2200,innerHeight/1350,.46);}
function drawSprite(img,meta,x,y,unit){const b=meta.sourceRect,a=meta.footAnchorInSourceRect;ctx.drawImage(img,b.x,b.y,b.width,b.height,x-a.x*unit,y-a.y*unit,b.width*unit,b.height*unit);}
function drawWorld(time,dt){ctx.clearRect(0,0,innerWidth,innerHeight);view=camera(state.player,innerWidth,innerHeight,scale);const img=images[imageKey()];ctx.drawImage(img,-view.x,-view.y,WORLD.width*scale,WORLD.height*scale);if(transition>0&&previousImage){ctx.globalAlpha=transition;ctx.drawImage(previousImage,-view.x,-view.y,WORLD.width*scale,WORLD.height*scale);ctx.globalAlpha=1;transition=Math.max(0,transition-dt*.55);}
 const px=p=>({x:p.x*WORLD.width*scale-view.x,y:p.y*WORLD.height*scale-view.y});
 // Water glints and a slow breeze give the world motion without changing the teaching data.
 if(state.settings.motion&&state.region==='coast'){for(let n=0;n<16;n++){const p=px({x:.76+(n%4)*.05,y:.58+Math.floor(n/4)*.07});ctx.globalAlpha=.09+.07*Math.sin(time/800+n);ctx.fillStyle='#d9f1e6';ctx.fillRect(p.x,p.y,10*scale,scale);}ctx.globalAlpha=1;}
 const pad=px(r().pad);ctx.save();ctx.translate(pad.x,pad.y);ctx.rotate(-.3);const craft=images.craft;ctx.drawImage(craft,-100*scale,-64*scale,190*scale,127*scale);ctx.restore();
 const sprites=r().spots.filter(p=>p.kind==='npc').map(p=>({p,y:p.y,npc:true}));sprites.push({p:state.player,y:state.player.y,npc:false});sprites.sort((a,b)=>a.y-b.y).forEach(({p,npc})=>{const xy=px(p);ctx.save();ctx.fillStyle='#132b3038';ctx.beginPath();ctx.ellipse(xy.x,xy.y+2*scale,14*scale,4*scale,0,0,Math.PI*2);ctx.fill();ctx.restore();if(npc){const meta=npcFrames.npcs[p.npc];drawSprite(images.npcs,meta,xy.x,xy.y,.135*scale*(.65+p.y*.45));}else{const index=moving&&state.settings.motion?Math.floor(gaitTime/.14)%4:1,meta=playerFrames.player.frames.find(f=>f.direction===facing&&f.gaitIndex===index);drawSprite(images.player,meta,xy.x,xy.y,.50*scale*(.65+p.y*.45));}});
 const heat=px({x:.21,y:.45});if(state.flags.greenhouse&&state.settings.motion){for(let n=0;n<6;n++){ctx.strokeStyle=`rgba(244,188,111,${.35+Math.sin(time/900+n)*.1})`;ctx.lineWidth=1.5;ctx.beginPath();const phase=(time/2000+n/6)%1;ctx.moveTo(heat.x+n*5,heat.y-phase*30);ctx.quadraticCurveTo(heat.x+n*5+8,heat.y-phase*30-15,heat.x+n*5,heat.y-phase*30-25);ctx.stroke();}}
 renderTargets(px);
}
let targetSignature='';
function renderTargets(px){if(flight||!started){$('#world-targets').hidden=true;return;}$('#world-targets').hidden=false;const signature=state.region;if(targetSignature!==signature){$('#world-targets').innerHTML=r().spots.map(p=>`<button class="world-target ${p.kind==='npc'?'npc':''}" data-act="approach" data-id="${p.id}" aria-label="${esc(p.label)}"><span>${esc(p.label)}</span></button>`).join('');targetSignature=signature;}
 const near=nearest();for(const p of r().spots){const el=document.querySelector(`.world-target[data-id="${p.id}"]`),xy=px(p);el.style.left=xy.x+'px';el.style.top=(xy.y-(p.kind==='npc'?105*scale*(.65+p.y*.45):0))+'px';el.hidden=xy.x<-50||xy.x>innerWidth+50||xy.y<-20||xy.y>innerHeight+100;el.classList.toggle('near',near?.id===p.id&&near.d<.14);el.classList.toggle('active',arrivalId===p.id);}
 if(!panel.open&&!speechOn&&near&&near.d<.14){$('#context').hidden=false;contextHTML(`<button class="context-prompt" data-act="interact"><kbd>E</kbd>${esc(near.label)}</button>`);}else $('#context').hidden=true;
}
function earthPath(){ctx.beginPath();const polygons=earth.features.flatMap(f=>f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates);for(const poly of polygons){for(const ring of poly){let previous=null;for(const [lon,lat]of ring){const x=innerWidth*(.08+(lon+180)/360*.84),y=innerHeight*(.17+(90-lat)/180*.68);if(!previous||Math.abs(x-previous.x)>innerWidth*.4)ctx.moveTo(x,y);else ctx.lineTo(x,y);previous={x,y};}ctx.closePath();}}ctx.fill();}
function drawFlight(time){ctx.clearRect(0,0,innerWidth,innerHeight);const g=ctx.createRadialGradient(innerWidth*.54,innerHeight*.4,10,innerWidth*.5,innerHeight*.5,innerWidth*.7);g.addColorStop(0,'#255c66');g.addColorStop(1,'#112a36');ctx.fillStyle=g;ctx.fillRect(0,0,innerWidth,innerHeight);ctx.strokeStyle='#b9d7c315';for(let x=0;x<12;x++){ctx.beginPath();ctx.moveTo(innerWidth*(.08+x*.076),innerHeight*.17);ctx.lineTo(innerWidth*(.08+x*.076),innerHeight*.85);ctx.stroke();}for(let y=0;y<7;y++){ctx.beginPath();ctx.moveTo(innerWidth*.08,innerHeight*(.17+y*.113));ctx.lineTo(innerWidth*.92,innerHeight*(.17+y*.113));ctx.stroke();}ctx.fillStyle='#59766f';earthPath();ctx.strokeStyle='#b8cfac55';ctx.lineWidth=.6;ctx.stroke();
 if(state.settings.motion)for(let n=0;n<14;n++){const x=((n*173+time*.012)%innerWidth),y=innerHeight*(.22+(n%5)*.115);ctx.fillStyle='#d5e6df08';ctx.beginPath();ctx.ellipse(x,y,60+(n%3)*30,20,0,0,Math.PI*2);ctx.fill();}
 const x=innerWidth*(.08+flightPos.x*.84),y=innerHeight*(.17+flightPos.y*.68);ctx.save();ctx.translate(x,y);ctx.rotate((flightAngle-146)*Math.PI/180);ctx.shadowColor='#d0c89455';ctx.shadowBlur=20;ctx.drawImage(images.craft,-55,-37,110,73);ctx.restore();
 $('#world-targets').hidden=true;$('#flight-targets').hidden=false;if(!$('#flight-targets').querySelector('.flight-destination'))$('#flight-targets').innerHTML=destinations.map(d=>{const near=Math.hypot(d.x-flightPos.x,(d.y-flightPos.y)*.55)<.035;return `<button class="flight-destination ${near?'near':''}" data-act="flyTo" data-region="${d.region}" style="left:${8+d.x*84}%;top:${17+d.y*68}%">${esc(d.name)}${near?'<small>E om te landen</small>':''}</button>`;}).join('');for(const d of destinations){const el=document.querySelector(`.flight-destination[data-region="${d.region}"]`),near=Math.hypot(d.x-flightPos.x,(d.y-flightPos.y)*.55)<.035;el?.classList.toggle('near',near);if(el){let small=el.querySelector('small');if(near&&!small){small=document.createElement('small');small.textContent='E om te landen';el.append(small);}else if(!near&&small)small.remove();}}$('#context').hidden=false;const near=destinations.find(d=>Math.hypot(d.x-flightPos.x,(d.y-flightPos.y)*.55)<.035);contextHTML(`<button class="context-prompt" data-act="${near?'land':'map'}" ${near?'data-region="'+near.region+'"':''}><kbd>${near?'E':'M'}</kbd>${near?'Land in '+esc(near.name):'Kies je bestemming of vlieg zelf'}</button>`);
}
function frame(time){const dt=Math.min(.05,(time-last)/1000||0);last=time;if(state){if(started&&!panel.open&&!speechOn){let dx=Number(keys.has('right'))-Number(keys.has('left')),dy=Number(keys.has('down'))-Number(keys.has('up'));if(flight){if(!dx&&!dy&&flightGoal){dx=flightGoal.x-flightPos.x;dy=flightGoal.y-flightPos.y;if(Math.hypot(dx,dy)<.005){flightPos={...flightGoal};flightGoal=null;dx=dy=0;}}const length=Math.hypot(dx,dy);if(length){flightPos.x=Math.max(.02,Math.min(.98,flightPos.x+dx/length*dt*.14));flightPos.y=Math.max(.04,Math.min(.96,flightPos.y+dy/length*dt*.20));flightAngle=Math.atan2(dy,dx)*180/Math.PI;}}else{if(!dx&&!dy&&route.length){dx=(route[0].x-state.player.x)*1.5;dy=route[0].y-state.player.y;if(Math.hypot(dx,dy)<.004){state.player={...route.shift()};dx=dy=0;}}const old={...state.player};state.player=move(state.player,dx,dy,dt,state.region,.073);moving=Math.hypot(old.x-state.player.x,old.y-state.player.y)>1e-6;if(moving){gaitTime+=dt;facing=Math.abs(dx)>Math.abs(dy)?dx>0?'east':'west':dy>0?'south':'north';}else if(!route.length)gaitTime=0;if(!route.length&&arrivalId){const id=arrivalId;arrivalId=null;const p=r().spots.find(p=>p.id===id);if(p&&Math.hypot((p.x-state.player.x)*1.5,p.y-state.player.y)<.15)interactSpot(p);}}}else moving=false;if(flight&&started)drawFlight(time);else{$('#flight-targets').hidden=true;drawWorld(time,dt);}}requestAnimationFrame(frame);}

document.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(!b||b.disabled)return;const act=b.dataset.act;const actions={start,intro,close:closePanel,endSpeech:()=>{speechOn=false;$('#dialogue').hidden=true;renderHUD();},quest,find:()=>find(b.dataset.kind),scan:stepScan,map,book,glossary:()=>glossary(),episodeConcepts:()=>glossary(current().concepts),settings,upgrades,compare,compareShow,completeEpisode,storyRoute,approach:()=>approach(b.dataset.id),interact,futureCompare,toolUse:()=>toolUse(Number(b.dataset.index)),npcTopic:()=>npc(Number(b.dataset.npc),Number(b.dataset.topic)),era:()=>setEra(b.dataset.era),saveFuture,flyTo:()=>flyTo(b.dataset.region),land:()=>land(b.dataset.region),activity:()=>activityAction(b),fieldAnswer:()=>fieldAnswer(b),research,export:exportSave,admin:adminPrompt,adminLogin,adminOverview,adminVisit:()=>adminVisit(Number(b.dataset.index)),adminRegion:()=>{if(admin.active){flight=false;state.region=b.dataset.region;state.era='now';state.player={...r().spawn};closePanel();renderHUD();}},adminActivity:()=>adminActivity(b.dataset.kind),adminExit,revisit:()=>revisit(Number(b.dataset.index)),motion:()=>{state.settings.motion=!state.settings.motion;persist();settings();},home:()=>{closePanel();persist();landing();},reset:()=>{state=fresh();initModels(state);persist();panel.close();flight=false;landing();}};actions[act]?.();});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.note){state.notes[el.dataset.note]=el.value;persist();}if(el.dataset.model){state.models[el.dataset.model]??={};state.models[el.dataset.model][el.dataset.field]=el.type==='checkbox'?el.checked:el.value.trim()!==''&&Number.isFinite(Number(el.value))?Number(el.value):el.value;persist();const key=el.dataset.model+'.'+el.dataset.field;document.querySelectorAll('[data-field-value]').forEach(o=>{if(o.dataset.fieldValue===key)o.textContent=el.type==='checkbox'?(el.checked?'aan':'uit'):el.value;});if(activity){const temp=document.createElement('div');temp.innerHTML=renderActivity(activity,state,core.concepts);const old=$('#panel-body .activity-live'),newLive=temp.querySelector('.activity-live');if(old&&newLive)old.innerHTML=newLive.innerHTML;}}});
document.addEventListener('change',async e=>{if(e.target.dataset.model&&activity)renderCurrentActivity();if(e.target.id==='import'){try{const file=e.target.files[0];if(!file||file.size>2e6)throw Error();const data=JSON.parse(await file.text());if(data.version!==1)throw Error();state=restore(data);initModels(state);persist();closePanel();flight=false;landing();toast('Veldboek geopend.');}catch{toast('Dit is geen geldig Atlas-veldboek.');}}});
const keyDir=k=>({w:'up',arrowup:'up',a:'left',arrowleft:'left',s:'down',arrowdown:'down',d:'right',arrowright:'right'})[k.toLowerCase()];
document.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,[contenteditable]')){if(e.key==='Enter'&&e.target.id==='admin-code')adminLogin();return;}if(e.key==='Escape'){panel.close();speechOn=false;$('#dialogue').hidden=true;stop();return;}if(!started||e.ctrlKey||e.metaKey||e.altKey||panel.open||speechOn)return;const d=keyDir(e.key);if(d){e.preventDefault();route=[];arrivalId=null;flightGoal=null;keys.add(d);return;}const actions={e:interact,q:quest,n:book,m:map,t:()=>{if(state.region==='coast')find('portal');else toast('Het tijdvenster staat in het kustobservatorium.');},f:()=>{if(flight)interact();else find('craft');}};actions[e.key.toLowerCase()]?.();});
document.addEventListener('keyup',e=>{const d=keyDir(e.key);if(d){keys.delete(d);persist();}});window.addEventListener('blur',stop);document.addEventListener('visibilitychange',()=>{if(document.hidden){stop();persist();}});window.addEventListener('beforeunload',persist);
canvas.addEventListener('pointerdown',e=>{if(!started||panel.open||speechOn)return;keys.clear();arrivalId=null;if(flight){flightGoal={x:Math.max(.02,Math.min(.98,(e.clientX/innerWidth-.08)/.84)),y:Math.max(.04,Math.min(.96,(e.clientY/innerHeight-.17)/.68))};return;}const target={x:(e.clientX+view.x)/(WORLD.width*scale),y:(e.clientY+view.y)/(WORLD.height*scale)};route=pathTo(state.player,target,state.region);});
document.querySelectorAll('[data-dir]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();route=[];arrivalId=null;flightGoal=null;keys.add(b.dataset.dir);b.setPointerCapture(e.pointerId);});const up=()=>{keys.delete(b.dataset.dir);persist();};b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);});
window.addEventListener('resize',resize);panel.addEventListener('cancel',()=>{activity=null;stop();});
async function loadImage(name,url){const img=new Image();img.src=url;await img.decode();images[name]=img;}
try{const data=await Promise.all(['core.json','assets/player-frames.json','assets/npc-frames.json','assets/earth-land.geojson'].map(async url=>{const r=await fetch(url);if(!r.ok)throw Error('De wereldbestanden worden klaargezet.');return r.json();}));[core,playerFrames,npcFrames,earth]=data;await Promise.all([['glacier','glacier.webp'],['mangrove','mangrove.webp'],['coast-now','coast-now.webp'],['coast-pressure','coast-pressure.webp'],['coast-recovery','coast-recovery.webp'],['workshop','workshop.webp'],['valley','valley.webp'],['player','player-walk.png'],['craft','survey-craft.png'],['npcs','npcs.png']].map(([name,file])=>loadImage(name,'assets/'+file)));let raw;try{raw=JSON.parse(localStorage.getItem(KEY));}catch{}state=restore(raw);initModels(state);if(!walkable(state.player,state.region))state.player={...r().spawn};resize();$('#loading').hidden=true;landing();requestAnimationFrame(frame);}catch(e){$('#loading').innerHTML=`<strong>ATLAS</strong><span>${esc(e.message)}</span><button class="btn" onclick="location.reload()">Opnieuw laden</button>`;}
